namespace sv_821c2e983995460ea8cd2f823cec75d5.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@* Step indicator bar showing progress through the application steps *@

<div class="step-indicator">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <div class="step @stepClass" @onclick="() => OnStepClick(stepIndex)">
            <div class="step-circle">
                @if (stepIndex < CurrentStep)
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>
        @if (i < StepNames.Length - 1)
        {
            <div class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></div>
        }
    }
</div>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter, EditorRequired]
    public int CurrentStep { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<int> OnStepSelected { get; set; }

    private string GetStepClass(int index)
    {
        if (index == CurrentStep) return "active";
        if (index < CurrentStep) return "completed";
        return "dimmed";
    }

    private async Task OnStepClick(int index)
    {
        // Only allow clicking completed steps
        if (index < CurrentStep)
        {
            await OnStepSelected.InvokeAsync(index);
        }
    }
}

@using sv_821c2e983995460ea8cd2f823cec75d5.Models

<div class="step-content">
    <h3>Personal Information</h3>

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" class="form-control" @bind="FullName" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" class="form-control" @bind="Email" @bind:event="oninput" />
        @if (!string.IsNullOrEmpty(EmailError))
        {
            <span class="field-error">@EmailError</span>
        }
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" class="form-control" @bind="Phone" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <input id="address" type="text" class="form-control" @bind="Address" @bind:event="oninput" />
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<PersonalInfo> OnNext { get; set; }

    [Parameter, EditorRequired]
    public IApplicationService ApplicationService { get; set; } = default!;

    private string? ValidationError;
    private string? EmailError;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ValidationError = null;
        EmailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ValidationError = "All fields are required.";
            return;
        }

        IsValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Email);
            if (!emailValid)
            {
                EmailError = "Please enter a valid email address.";
                return;
            }

            await OnNext.InvokeAsync(new PersonalInfo(FullName, Email, Phone, Address));
        }
        finally
        {
            IsValidating = false;
        }
    }
}

@using sv_821c2e983995460ea8cd2f823cec75d5.Models

<div class="step-content">
    <h3>Work History</h3>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        var entry = Entries[index];
        <WorkEntryForm
            Index="index"
            Company="@entry.Company"
            Title="@entry.Title"
            StartDate="@entry.StartDate"
            EndDate="@entry.EndDate"
            IsCurrent="@entry.IsCurrent"
            Description="@entry.Description"
            CanRemove="@(Entries.Count > 1)"
            OnRemove="() => RemoveEntry(index)"
            OnChanged="data => UpdateEntry(index, data)" />
    }

    <button class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<EntryModel> Entries { get; set; } = new();

    [Parameter, EditorRequired]
    public EventCallback<List<EntryModel>> OnNext { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnBack { get; set; }

    private string? ValidationError;

    public class EntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private void AddEntry()
    {
        Entries.Add(new EntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private void UpdateEntry(int index, WorkEntryForm.WorkEntryData data)
    {
        if (index < Entries.Count)
        {
            Entries[index].Company = data.Company;
            Entries[index].Title = data.Title;
            Entries[index].StartDate = data.StartDate;
            Entries[index].EndDate = data.EndDate;
            Entries[index].IsCurrent = data.IsCurrent;
            Entries[index].Description = data.Description;
        }
    }

    private async Task HandleNext()
    {
        ValidationError = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ValidationError = "Each position must have a company name and job title.";
                return;
            }
        }

        await OnNext.InvokeAsync(Entries);
    }
}

@using sv_821c2e983995460ea8cd2f823cec75d5.Models

<div class="step-content">
    <h3>References</h3>
    <p class="step-description">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        var reference = References[index];
        <ReferenceForm
            Index="index"
            Name="@reference.Name"
            Relationship="@reference.Relationship"
            Email="@reference.Email"
            Phone="@reference.Phone"
            CanRemove="@(References.Count > 2)"
            OnRemove="() => RemoveReference(index)"
            OnChanged="data => UpdateReference(index, data)" />
    }

    @if (References.Count < 3)
    {
        <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new();

    [Parameter, EditorRequired]
    public EventCallback<List<ReferenceModel>> OnNext { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnBack { get; set; }

    private string? ValidationError;

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private void UpdateReference(int index, ReferenceForm.ReferenceData data)
    {
        if (index < References.Count)
        {
            References[index].Name = data.Name;
            References[index].Relationship = data.Relationship;
            References[index].Email = data.Email;
            References[index].Phone = data.Phone;
        }
    }

    private async Task HandleNext()
    {
        ValidationError = null;

        if (References.Count < 2)
        {
            ValidationError = "Please provide at least 2 references.";
            return;
        }

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ValidationError = "All fields are required for each reference.";
                return;
            }
        }

        await OnNext.InvokeAsync(References);
    }
}

@using sv_821c2e983995460ea8cd2f823cec75d5.Models

<div class="step-content">
    <h3>Review & Submit</h3>
    <p class="step-description">Please review your application before submitting.</p>

    @if (IsSubmitted)
    {
        <div class="submission-confirmation">
            <div class="success-icon">&#10003;</div>
            <h4>Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>We will review your application and get back to you soon.</p>
        </div>
    }
    else
    {
        <div class="review-section">
            <div class="review-section-header">
                <h4>Personal Information</h4>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            <dl class="review-details">
                <dt>Full Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </div>

        <div class="review-section">
            <div class="review-section-header">
                <h4>Work History</h4>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <div class="review-dates">
                        @entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                    </div>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="review-description">@entry.Description</p>
                    }
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-section-header">
                <h4>References</h4>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var reference in References)
            {
                <div class="review-reference">
                    <strong>@reference.Name</strong> (@reference.Relationship)
                    <div>@reference.Email &bull; @reference.Phone</div>
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-section-header">
                <h4>Cover Letter</h4>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
            </div>
            <p class="review-cover-letter">@CoverLetter</p>
        </div>

        @if (!string.IsNullOrEmpty(SubmitError))
        {
            <div class="validation-error">@SubmitError</div>
        }

        <div class="step-buttons">
            <button class="btn btn-outline" @onclick="OnBack">Back</button>
            <button class="btn btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfo Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryData> WorkEntries { get; set; } = new();
    [Parameter, EditorRequired] public List<ReferenceData> References { get; set; } = new();
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<int> OnEditSection { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback OnSubmit { get; set; }
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int? ApplicationId { get; set; }
    [Parameter] public string? SubmitError { get; set; }

    public record WorkEntryData(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
    public record ReferenceData(string Name, string Relationship, string Email, string Phone);

    private async Task HandleSubmit()
    {
        await OnSubmit.InvokeAsync();
    }
}

