    <div class="form-group">
        <label for="coverLetter">Write your cover letter</label>
        <textarea id="coverLetter" class="form-control cover-letter-textarea" rows="12"
                  maxlength="@MaxLength"
                  @bind="CoverLetter" @bind:event="oninput"></textarea>
        <div class="character-count @(CoverLetter.Length > MaxLength ? "over-limit" : "")">
